export function createAIManagementUI({api,esc,getState,openDialog,closeDialog,toast}){
 let active=false,org='',data,sequence=0,evaluating=false,internal;
 const url=()=>'/api/portal/ai-management?org='+encodeURIComponent(org),usd=n=>typeof n==='number'?n.toLocaleString('pt-BR',{style:'currency',currency:'USD',minimumFractionDigits:4}):'Não medido';
 const button=(text,action,id='')=>`<button type="button" class="p-button secondary" data-ai="${action}" data-id="${esc(id)}">${text}</button>`;
 async function load(){const t=++sequence;try{const [r,settings]=await Promise.all([api(url()),api('/api/portal/admin-settings?org='+encodeURIComponent(org))]);if(!active||t!==sequence)return;data=r;internal=settings;paint();}catch(e){if(active&&t===sequence)document.querySelector('#ai-management').innerHTML='<p role="alert">'+esc(e.message)+'</p>';}}
 function paint(){const r=data.report,batches=[...new Set(data.evaluations.map(e=>e.batch))];document.querySelector('#ai-management').innerHTML=`<label class="p-field"><span>Empresa</span><select id="ai-company" ${evaluating?'disabled':''}>${data.clients.map(c=>`<option value="${esc(c.id)}" ${c.id===org?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>
 <section class="finance-panel"><h2>Controles internos da empresa</h2><p>Somente a equipe Helpu altera estes controles. Eles não são a franquia comercial do cliente, que aparece em Meu plano.</p><form id="internal-settings"><div class="form-grid">${['dailyRuns','dailyMedia','dailyMessages'].map((k,i)=>`<label class="p-field"><span>${['Execuções de IA por dia','Gerações de mídia por dia','Mensagens por dia'][i]}</span><input name="${k}" value="${esc(internal.policy[k])}" required></label>`).join('')}<label class="p-field"><span>Endereço público do portal</span><input name="publicBaseUrl" type="url" value="${esc(internal.policy.publicBaseUrl||'')}"></label></div><p>Informe um número inteiro. ${internal.policy.usageTestingEnabled?'Para testes, use unlimited para remover o limite interno.':'Uso sem limite não está habilitado para esta empresa.'}</p><label class="checkline"><input name="enabled" type="checkbox" ${internal.policy.enabled?'checked':''}> Rotina interna diária de planejamento por IA</label><label class="checkline"><input name="autoMedia" type="checkbox" ${internal.policy.autoMedia?'checked':''}> Produzir imagens para as sugestões da rotina interna</label><p>Esta rotina interna é separada dos pedidos agendados pelo cliente e não substitui a consultoria humana contratada.</p><button class="p-button primary">Salvar controles internos</button><p role="status" id="internal-status"></p></form><p>Uso de hoje: ${internal.usage.used.dailyRuns} execuções de IA · ${internal.usage.used.dailyMedia} gerações de mídia.</p>${internal.policy.usageTestingEnabled?'<button type="button" class="p-button secondary" id="internal-reset">Zerar uso interno de teste</button>':''}<p>Zerar preserva o histórico e não altera créditos do plano, cobranças ou saldo dos fornecedores.</p></section>
 <section class="finance-panel"><h2>Consumo dos últimos 30 dias</h2><p>${r.calls} respostas registradas · ${r.priced} com estimativa de preço · ${r.unpriced} sem custo completo.</p><h3>Parcela estimada: ${r.priced?usd(r.knownUsd):'Não medida'}</h3><p>Estimativa em dólares, não valor da fatura. Texto e imagens entram somente quando há medição e tarifa suficientes. Renderização, armazenamento, WhatsApp e chamadas sem medição não estão incluídos nessa parcela. Custos desconhecidos não são zero. Tarifas conferidas em ${esc(data.priceDate)}. <a href="${esc(data.priceSource)}" target="_blank" rel="noopener">Tabela oficial</a>.</p><p>Tempo médio das respostas medidas: ${r.averageLatencyMs===null?'não medido':Math.round(r.averageLatencyMs/1000)+' s'} · ${r.failedJobs} pedidos com falha/bloqueio/incerteza · ${r.retriedJobs} com mais de uma tentativa.</p><p>Custo médio medido de IA por criação aprovada iniciada neste período: ${usd(r.averageApprovedProductionUsd)}. Cobertura: ${r.approvedMeasured} de ${r.approvedWithUsage} criações aprovadas com consumo no período. Não inclui conversa anterior, infraestrutura ou atendimento.</p><div class="ai-table-wrap"><table class="commerce-table"><thead><tr><th>Tarefa / modelo</th><th>Chamadas / tokens</th><th>Parcela estimada</th></tr></thead><tbody>${r.groups.map(g=>`<tr><td>${esc(data.tasks[g.operation]||g.operation)}<br>${esc(g.model||'Modelo não informado')}</td><td>${g.calls}<br>Entrada: ${g.tokens.input??"?"}<br>Cache: ${g.tokens.cachedInput??"?"}<br>Saída: ${g.tokens.output??"?"}<br>${g.tokenCoverage}/${g.calls} medidas</td><td>${g.priced?usd(g.knownUsd):'Não medido'}<br>${g.priced}/${g.calls} com preço</td></tr>`).join('')}</tbody></table></div><details><summary>Pedidos com mais chamadas</summary>${r.requests.map(q=>`<p>${esc(q.id)} · ${q.calls} chamadas · ${esc(q.state)} · ${q.priced?usd(q.knownUsd):'Não medido'} (${q.priced}/${q.calls})</p>`).join('')||'<p>Nenhuma medição disponível.</p>'}</details></section>
 <section class="finance-panel"><h2>Modelo por tarefa</h2><p>A configuração atual é preservada até você ativar uma mudança. Tarefas estruturadas menores permanecem no modelo já configurado. Erros técnicos não acionam automaticamente outro modelo.</p><form id="ai-routing">${Object.entries(data.tasks).map(([k,v])=>`<label class="p-field"><span>${esc(v)} · atual: ${esc(data.effective[k])}</span><select name="${k}"><option value="">Manter configuração da empresa/servidor</option>${data.models.map(m=>`<option value="${m}" ${data.policy.routes[k]===m?'selected':''}>${m}</option>`).join('')}</select></label>`).join('')}<label class="p-field"><span>Lote de comparação conferido</span><select name="batch"><option value="">Selecione</option>${batches.map(b=>`<option>${esc(b)}</option>`).join('')}</select></label><label class="p-field"><span>Motivo e tarefas verificadas</span><textarea name="reason" minlength="8" maxlength="1000" required></textarea></label><label class="checkline"><input name="quality" type="checkbox"> Conferi os resultados e validei casos reais anonimizados das tarefas que vou alterar, incluindo ferramentas, contexto e qualidade das entregas.</label><p>A comparação isolada abaixo testa contexto e escolha de ferramentas. Ela não substitui a revisão de roteiros, imagens e vídeos reais. Ativar modelos exige aprovação nos oito casos e comparação completa.</p><button class="p-button primary" ${evaluating?'disabled':''}>Salvar roteamento</button></form></section>
 <section class="finance-panel"><h2>Comparar Sol e Astra</h2><p>Oito casos fictícios: correções, materiais anteriores, música, todas as imagens, anexo sem pedido, produção em andamento, referência de estilo e marca conflitante. Mesmas instruções e esforço nos dois modelos. Nenhum arquivo será gerado nem enviado a clientes.</p><p>São 16 avaliações pagas, com até três chamadas de 2.000 tokens de saída por avaliação (máximo de 48 chamadas). Iniciar esta comparação consome a API. Ela não troca o modelo do portal.</p>${button(evaluating?'Comparação em andamento':'Iniciar comparação','evaluate')}<p id="ai-progress" role="status"></p>${batches.map(b=>`<details><summary>Lote ${esc(b)} · ${data.evaluations.filter(e=>e.batch===b&&e.passed).length}/16 verificações aprovadas</summary>${data.evaluations.filter(e=>e.batch===b).map(e=>`<article class="commerce-item"><strong>${esc(data.cases.find(c=>c.id===e.caseId)?.name||e.caseId)} · ${esc(e.model)}</strong><p>${e.state==='running'?'Em andamento / confirmação pendente':e.passed?'Verificação automática aprovada':'Precisa de análise'} ${esc((e.notes||[]).join('; '))}</p><pre class="ai-eval-output">${esc(JSON.stringify(e.output||[],null,2))}</pre></article>`).join('')}</details>`).join('')}</section>
 <section class="finance-panel"><h2>Histórico e reversão</h2>${data.history.map(h=>`<article class="commerce-item"><p>${new Date(h.createdAt).toLocaleString('pt-BR')} · ${esc(h.reason)}</p>${button('Restaurar configuração anterior','rollback',h.id)}</article>`).join('')||'<p>Nenhuma alteração.</p>'}</section><section class="finance-panel"><h2>O que não chama IA</h2><p>Consultar saldo, aprovar, baixar, preencher cadastro, registrar boleto e confirmar pagamento não precisam de geração de IA. Uma conversa livre com o Astra pode consumir API. Franquia comercial de entregas e consumo do fornecedor são controles separados.</p></section>`;
 document.querySelector('#internal-settings').addEventListener('submit',async e=>{e.preventDefault();const form=e.target,values=new FormData(form),policy=Object.fromEntries(['dailyRuns','dailyMedia','dailyMessages','publicBaseUrl'].map(k=>[k,values.get(k)]));policy.enabled=values.get('enabled')==='on';policy.autoMedia=values.get('autoMedia')==='on';form.querySelector('button').disabled=true;try{await api('/api/portal/admin-settings?org='+encodeURIComponent(org),'POST',{action:'save',expectedUpdatedAt:internal.company.updatedAt,policy});await load();toast('Controles internos salvos.');}catch(e){form.querySelector('button').disabled=false;document.querySelector('#internal-status').textContent=e.message;}});
 document.querySelector('#internal-reset')?.addEventListener('click',async e=>{e.target.disabled=true;try{await api('/api/portal/admin-settings?org='+encodeURIComponent(org),'POST',{action:'reset',expectedUpdatedAt:internal.company.updatedAt});await load();toast('Uso interno de teste zerado.');}catch(err){e.target.disabled=false;toast(err.message,true);}});
 document.querySelector('#ai-routing').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target),routes=Object.fromEntries(Object.keys(data.tasks).filter(k=>f.get(k)).map(k=>[k,f.get(k)]));try{await api(url(),'POST',{action:'save',routes,version:data.policy.version,batch:f.get('batch'),reason:f.get('reason'),qualityReviewed:f.get('quality')==='on'});await load();toast('Roteamento salvo. As próximas chamadas usarão esta configuração.');}catch(e){toast(e.message,true);}});
 }
 document.addEventListener('change',e=>{if(active&&e.target.id==='ai-company'&&!evaluating){org=e.target.value;load();}});
 document.addEventListener('click',e=>{const b=e.target.closest('[data-ai]');if(!active||!b||evaluating)return;if(b.dataset.ai==='evaluate'){
  openDialog('Comparação com consumo da API',`<form id="ai-confirm"><p>Executar 16 avaliações com dados fictícios, até 48 chamadas pagas. Nenhuma configuração será alterada automaticamente.</p><label class="checkline"><input type="checkbox" required> Autorizo as chamadas da comparação.</label><button class="p-button primary">Comparar agora</button></form>`);
  document.querySelector('#ai-confirm').addEventListener('submit',async e=>{e.preventDefault();closeDialog();evaluating=true;paint();const batch=crypto.randomUUID(),target=url(),company=org;let finished=0;try{for(const c of data.cases)for(const model of data.models){if(!active||org!==company)throw new Error('Comparação interrompida. As tentativas já feitas ficam no histórico.');document.querySelector('#ai-progress').textContent=`${finished}/16 · ${c.name} · ${model}`;const result=await api(target,'POST',{action:'evaluate',caseId:c.id,model,batch,confirmed:true});finished++;if(result.state!=='complete')throw new Error('Uma tentativa não foi confirmada. Confira o histórico antes de repetir.');}toast('Comparação concluída. Revise os resultados antes de ativar.');}catch(e){toast(e.message,true);}finally{evaluating=false;if(active&&org===company)await load();}});
 }else if(b.dataset.ai==='rollback'){openDialog('Restaurar configuração anterior','<form id="ai-rollback"><label class="p-field"><span>Motivo da reversão</span><textarea name="reason" required minlength="8"></textarea></label><button class="p-button primary">Restaurar</button></form>');document.querySelector('#ai-rollback').addEventListener('submit',async e=>{e.preventDefault();try{await api(url(),'POST',{action:'rollback',historyId:b.dataset.id,version:data.policy.version,reason:new FormData(e.target).get('reason')});closeDialog();await load();toast('Configuração anterior restaurada.');}catch(e){toast(e.message,true);}});}});
 return {page(){org=getState().company.id;return '<section class="page-heading"><div><p class="overline">ADMINISTRAÇÃO</p><h1>Inteligência e consumo</h1><p>Custo medido, comparação de qualidade e modelos por tarefa.</p></div></section><div id="ai-management">Carregando…</div>';},mount(view){active=view==='intelligence';++sequence;if(active)load();}};
}
